// Generates the client from the committed contract into src/generated.
// Never edit src/generated by hand: run `pnpm --filter @psstore/api-client
// run generate` after a change to contract/openapi.json.
import { URL, fileURLToPath } from 'node:url'
import { createClient } from '@hey-api/openapi-ts'
import { generatorConfig } from './generator-config.mjs'

const root = new URL('../../../', import.meta.url)

await createClient(
  generatorConfig({
    input: fileURLToPath(new URL('contract/openapi.json', root)),
    output: fileURLToPath(new URL('packages/api-client/src/generated', root)),
  }),
)
